import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry', () => {
  describe('execute', () => {
    function createRegistryAndExecute() {
      const registry = new ToolRegistry();
      const execute = jest.fn<(input: Record<string, unknown>) => Promise<string>>().mockResolvedValue('success');
      return {registry, execute};
    }

    function registerTool(
      registry: ToolRegistry,
      execute: jest.Mock<(...args: unknown[]) => unknown>,
      schemaProps: unknown,
      required: string[] = []
    ) {
      registry.register(
        {
          name: 'test-tool',
          description: 'A test tool',
          inputSchema: {
            type: 'object',
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            properties: schemaProps as any,
            required,
          },
        } as unknown as ToolDefinition,
        execute
      );
    }

    it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
      const {registry, execute} = createRegistryAndExecute();
      registerTool(registry, execute, {location: {type: 'string'}}, ['location']);

      const response = await registry.execute('test-tool', {});

      const calls = execute.mock.calls;
      expect({calls: calls.length, result: response.result}).toEqual({
        calls: 0,
        result: expect.stringContaining("must have required property 'location'"),
      });
    });

    it('passes valid input with an unlisted extra property through to the executor unchanged exactly once', async () => {
      const {registry, execute} = createRegistryAndExecute();
      registerTool(registry, execute, {location: {type: 'string'}}, ['location']);

      const input = {location: 'Paris', extra: 'data'};
      await registry.execute('test-tool', input);

      expect(execute.mock.calls).toEqual([[input]]);
    });

    it('rejects a wrong-typed field with a message naming the field path and expected type, without leaking the value', async () => {
      const {registry, execute} = createRegistryAndExecute();
      registerTool(registry, execute, {location: {type: 'string'}});

      const response = await registry.execute('test-tool', {location: 42});

      const calls = execute.mock.calls;
      expect({
        calls: calls.length,
        hasPath: typeof response.result === 'string' && response.result.includes('/location'),
        hasType: typeof response.result === 'string' && response.result.includes('must be string'),
        hasValue: typeof response.result === 'string' && response.result.includes('42'),
      }).toEqual({
        calls: 0,
        hasPath: true,
        hasType: true,
        hasValue: false,
      });
    });

    it('throws Unknown tool: <name> for an unregistered name', async () => {
      const {registry} = createRegistryAndExecute();
      await expect(registry.execute('non-existent', {})).rejects.toThrow('Unknown tool: non-existent');
    });

    it('validates a function-valued tool definition against the schema current at that call', async () => {
      const {registry, execute} = createRegistryAndExecute();
      let callCount = 0;
      registry.register(() => {
        callCount++;
        return {
          name: 'dynamic-tool',
          description: 'A dynamic tool',
          inputSchema: {
            type: 'object',
            properties: {flag: {type: callCount <= 2 ? 'string' : 'number'}},
          },
        } as unknown as ToolDefinition;
      }, execute);

      const r1 = await registry.execute('dynamic-tool', {flag: 'value'});
      const r2 = await registry.execute('dynamic-tool', {flag: 42});
      const r3 = await registry.execute('dynamic-tool', {flag: 'value'});

      const calls = execute.mock.calls;
      expect({
        calls: calls.length,
        r1,
        r2,
        r3IsNumberError: typeof r3.result === 'string' && r3.result.includes('must be number'),
      }).toEqual({
        calls: 2,
        r1: {result: 'success'},
        r2: {result: 'success'},
        r3IsNumberError: true,
      });
    });

    it('compiles a static tool schema once across multiple execute calls', async () => {
      const {registry, execute} = createRegistryAndExecute();
      registerTool(registry, execute, {location: {type: 'string'}});

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const internalAjv = (registry as any).ajv;
      const originalCompile = internalAjv.compile;

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const compileSpy = jest.fn((...args: any[]) => originalCompile.apply(internalAjv, args));
      internalAjv.compile = compileSpy;

      for (let i = 0; i < 10; i++) {
        await registry.execute('test-tool', {location: 'Paris'});
      }

      const executeCalls = execute.mock.calls;
      const compileCalls = compileSpy.mock.calls;
      expect({
        executeCalls: executeCalls.length,
        compileCalls: compileCalls.length,
      }).toEqual({
        executeCalls: 10,
        compileCalls: 0,
      });
    });
  });

  describe('register', () => {
    it('throws at registration time for an uncompilable static schema', () => {
      const {registry, execute} = createRegistryAndExecute();

      expect(() => {
        registerTool(registry, execute, {location: {type: 'invalid-type-xyz'}});
      }).toThrow('Failed to compile schema for tool test-tool');
    });
  });
});

import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';
import Ajv, {type ValidateFunction} from 'ajv';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  // @ts-expect-error ajv options type mismatch with eslint ajv 6 types
  private readonly ajv = new Ajv({strict: false, validateFormats: false});
  private readonly compiledSchemas = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    if (typeof definition !== 'function') {
      try {
        this.compiledSchemas.set(definition.inputSchema, this.ajv.compile(definition.inputSchema));
      } catch (e) {
        throw new Error(
          `Failed to compile schema for tool ${resolved.name}: ${e instanceof Error ? e.message : String(e)}`,
          {cause: e}
        );
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  // Validates input against inputSchema. See specs/hal-engine-tool-input-validation/spec.md
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }

    const resolvedDef = this.resolveDefinition(tool.definitionSource);
    let validate = this.compiledSchemas.get(resolvedDef.inputSchema);
    if (!validate) {
      validate = this.ajv.compile(resolvedDef.inputSchema) as ValidateFunction;
      this.compiledSchemas.set(resolvedDef.inputSchema, validate);
    }

    const validateFn = validate;
    if (!validateFn(input)) {
      const error = validateFn.errors?.[0];
      const message = error
        ? `${(error as {instancePath?: string}).instancePath ?? (error as {dataPath?: string}).dataPath} ${error.message}`.trim()
        : 'Invalid input';
      return {result: message};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

